-- procurement: suppliers, supplier price lists, purchase orders and what was received against them.
--   * Money is bigint minor units with an ISO 4217 code; quantities numeric(18,4) (the inventory scale).
--   * Ids are UUIDv7 generated by the server. tenant_id leads every key and index; RLS is forced on every table.
--   * Stock is NOT written here: receiving calls the inventory port, which owns the ledger (AGENTS.md rule 6).
CREATE SCHEMA procurement AUTHORIZATION wb_migrator;
GRANT USAGE ON SCHEMA procurement TO wb_app;

CREATE TABLE procurement.suppliers (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  name text NOT NULL CHECK (btrim(name) <> '' AND length(name) <= 120),
  contact_name text NOT NULL DEFAULT '' CHECK (length(contact_name) <= 120),
  email text NOT NULL DEFAULT '' CHECK (length(email) <= 254),
  phone text NOT NULL DEFAULT '' CHECK (length(phone) <= 40),
  address text NOT NULL DEFAULT '' CHECK (length(address) <= 500),
  payment_terms_days integer NOT NULL DEFAULT 0 CHECK (payment_terms_days BETWEEN 0 AND 365),
  lead_time_days integer NOT NULL DEFAULT 0 CHECK (lead_time_days BETWEEN 0 AND 365),
  currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  archived_at timestamptz,
  version integer NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT suppliers_pkey PRIMARY KEY (tenant_id, id)
);

-- One price per (supplier, variant, valid_from): a new price is a new row with a later valid_from.
CREATE TABLE procurement.supplier_prices (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  supplier_id uuid NOT NULL,
  variant_id uuid NOT NULL,
  unit_cost_minor bigint NOT NULL CHECK (unit_cost_minor >= 0),
  currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  min_order_qty numeric(18,4) NOT NULL CHECK (min_order_qty > 0),
  valid_from date NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT supplier_prices_pkey PRIMARY KEY (tenant_id, id),
  CONSTRAINT supplier_prices_supplier_fk FOREIGN KEY (tenant_id, supplier_id)
    REFERENCES procurement.suppliers (tenant_id, id),
  CONSTRAINT supplier_prices_version_uq UNIQUE (tenant_id, supplier_id, variant_id, valid_from)
);
-- Keyset list of one supplier's prices by id.
CREATE INDEX supplier_prices_list_idx ON procurement.supplier_prices (tenant_id, supplier_id, id);

-- Gapless is not required: the number is taken with one upsert per PO (same pattern as sales.invoice_sequences).
CREATE TABLE procurement.po_sequences (
  tenant_id uuid PRIMARY KEY,
  last_no bigint NOT NULL CHECK (last_no >= 1)
);

CREATE TABLE procurement.purchase_orders (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  po_no bigint NOT NULL CHECK (po_no >= 1),
  supplier_id uuid NOT NULL,
  branch_id uuid NOT NULL,
  location_id uuid NOT NULL,
  currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  status text NOT NULL CHECK (status IN ('draft', 'sent', 'partially_received', 'received', 'closed', 'cancelled')),
  expected_on date,
  notes text NOT NULL DEFAULT '' CHECK (length(notes) <= 2000),
  total_minor bigint NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  version integer NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  sent_at timestamptz,
  closed_at timestamptz,
  cancelled_at timestamptz,
  CONSTRAINT purchase_orders_pkey PRIMARY KEY (tenant_id, id),
  CONSTRAINT purchase_orders_no_uq UNIQUE (tenant_id, po_no),
  CONSTRAINT purchase_orders_supplier_fk FOREIGN KEY (tenant_id, supplier_id)
    REFERENCES procurement.suppliers (tenant_id, id)
);
-- Keyset list filtered by status (newest first walks id backwards).
CREATE INDEX purchase_orders_status_idx ON procurement.purchase_orders (tenant_id, status, id);

CREATE TABLE procurement.po_lines (
  tenant_id uuid NOT NULL,
  purchase_order_id uuid NOT NULL,
  line integer NOT NULL CHECK (line >= 1),
  variant_id uuid NOT NULL,
  ordered_qty numeric(18,4) NOT NULL CHECK (ordered_qty > 0),
  received_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK (received_qty >= 0),
  short_qty numeric(18,4) NOT NULL DEFAULT 0 CHECK (short_qty >= 0),
  unit_cost_minor bigint NOT NULL CHECK (unit_cost_minor >= 0),
  -- Rounded once per line, half up (the money package's rule), so the PO total is an exact sum of line totals.
  line_total_minor bigint GENERATED ALWAYS AS (round(ordered_qty * unit_cost_minor)::bigint) STORED,
  CONSTRAINT po_lines_pkey PRIMARY KEY (tenant_id, purchase_order_id, line),
  CONSTRAINT po_lines_variant_uq UNIQUE (tenant_id, purchase_order_id, variant_id),
  CONSTRAINT po_lines_po_fk FOREIGN KEY (tenant_id, purchase_order_id)
    REFERENCES procurement.purchase_orders (tenant_id, id)
);

CREATE TABLE procurement.po_receipts (
  tenant_id uuid NOT NULL,
  id uuid NOT NULL,
  purchase_order_id uuid NOT NULL,
  reference text NOT NULL DEFAULT '' CHECK (length(reference) <= 80),
  received_at timestamptz NOT NULL,
  received_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT po_receipts_pkey PRIMARY KEY (tenant_id, id),
  CONSTRAINT po_receipts_po_fk FOREIGN KEY (tenant_id, purchase_order_id)
    REFERENCES procurement.purchase_orders (tenant_id, id)
);
CREATE INDEX po_receipts_po_idx ON procurement.po_receipts (tenant_id, purchase_order_id, id);

-- Lot and expiry are recorded for traceability; inventory batches are created by the inventory module, not here.
CREATE TABLE procurement.po_receipt_lines (
  tenant_id uuid NOT NULL,
  receipt_id uuid NOT NULL,
  po_line integer NOT NULL CHECK (po_line >= 1),
  variant_id uuid NOT NULL,
  qty numeric(18,4) NOT NULL CHECK (qty > 0),
  unit_cost_minor bigint NOT NULL CHECK (unit_cost_minor >= 0),
  lot_code text CHECK (lot_code IS NULL OR length(lot_code) <= 60),
  expires_on date,
  CONSTRAINT po_receipt_lines_pkey PRIMARY KEY (tenant_id, receipt_id, po_line),
  CONSTRAINT po_receipt_lines_receipt_fk FOREIGN KEY (tenant_id, receipt_id)
    REFERENCES procurement.po_receipts (tenant_id, id)
);

-- Over-receipt tolerance per business, in basis points (500 = 5 %). No row means the default.
CREATE TABLE procurement.settings (
  tenant_id uuid PRIMARY KEY,
  over_receipt_bps integer NOT NULL DEFAULT 500 CHECK (over_receipt_bps BETWEEN 0 AND 5000),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE "procurement"."suppliers" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."suppliers" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."suppliers" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."supplier_prices" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."supplier_prices" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."supplier_prices" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."po_sequences" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."po_sequences" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."po_sequences" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."purchase_orders" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."purchase_orders" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."purchase_orders" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."po_lines" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."po_lines" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."po_lines" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."po_receipts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."po_receipts" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."po_receipts" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."po_receipt_lines" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."po_receipt_lines" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."po_receipt_lines" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
ALTER TABLE "procurement"."settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "procurement"."settings" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "procurement"."settings" USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);

-- Least privilege: no deletes except draft lines (replaced on draft edit), no truncation, and only the columns that
-- change are updatable. Receipts are append-only.
REVOKE UPDATE, DELETE, TRUNCATE ON ALL TABLES IN SCHEMA procurement FROM wb_app;
GRANT UPDATE (name, contact_name, email, phone, address, payment_terms_days, lead_time_days, currency, archived_at, version, updated_at)
  ON procurement.suppliers TO wb_app;
GRANT UPDATE (unit_cost_minor, currency, min_order_qty, updated_at) ON procurement.supplier_prices TO wb_app;
GRANT UPDATE (last_no) ON procurement.po_sequences TO wb_app;
GRANT UPDATE (status, expected_on, notes, total_minor, version, updated_at, sent_at, closed_at, cancelled_at)
  ON procurement.purchase_orders TO wb_app;
GRANT UPDATE (variant_id, ordered_qty, unit_cost_minor, received_qty, short_qty) ON procurement.po_lines TO wb_app;
GRANT DELETE ON procurement.po_lines TO wb_app;
GRANT UPDATE (over_receipt_bps, updated_at) ON procurement.settings TO wb_app;
